import{_ as a,o as e,c as i,ah as r}from"./chunks/framework.CPHJ30oF.js";const m=JSON.parse('{"title":"15-容器监控-cAdvisor-Prometheus-Grafana","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"监控为什么是容器化环境的基础","slug":"监控为什么是容器化环境的基础","link":"#监控为什么是容器化环境的基础","children":[]},{"level":2,"title":"组件角色","slug":"组件角色","link":"#组件角色","children":[{"level":3,"title":"cAdvisor","slug":"cadvisor","link":"#cadvisor","children":[]},{"level":3,"title":"Prometheus","slug":"prometheus","link":"#prometheus","children":[]},{"level":3,"title":"Grafana","slug":"grafana","link":"#grafana","children":[]}]},{"level":2,"title":"实战搭建概览","slug":"实战搭建概览","link":"#实战搭建概览","children":[]},{"level":2,"title":"关键指标","slug":"关键指标","link":"#关键指标","children":[{"level":3,"title":"容器资源指标","slug":"容器资源指标","link":"#容器资源指标","children":[]},{"level":3,"title":"服务健康指标","slug":"服务健康指标","link":"#服务健康指标","children":[]}]},{"level":2,"title":"常见落地实践","slug":"常见落地实践","link":"#常见落地实践","children":[{"level":3,"title":"1. 先从关键服务开始","slug":"_1-先从关键服务开始","link":"#_1-先从关键服务开始","children":[]},{"level":3,"title":"2. 结合告警","slug":"_2-结合告警","link":"#_2-结合告警","children":[]},{"level":3,"title":"3. 设计仪表盘","slug":"_3-设计仪表盘","link":"#_3-设计仪表盘","children":[]},{"level":3,"title":"4. 观察容器生命周期","slug":"_4-观察容器生命周期","link":"#_4-观察容器生命周期","children":[]}]},{"level":2,"title":"工程化建议","slug":"工程化建议","link":"#工程化建议","children":[]},{"level":2,"title":"常见误区","slug":"常见误区","link":"#常见误区","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"docker/15-容器监控-cAdvisor-Prometheus-Grafana.md","filePath":"docker/15-容器监控-cAdvisor-Prometheus-Grafana.md"}'),h={name:"docker/15-容器监控-cAdvisor-Prometheus-Grafana.md"};function n(t,l,s,d,o,c){return e(),i("div",null,[...l[0]||(l[0]=[r('<h1 id="_15-容器监控-cadvisor-prometheus-grafana" tabindex="-1">15-容器监控-cAdvisor-Prometheus-Grafana <a class="header-anchor" href="#_15-容器监控-cadvisor-prometheus-grafana" aria-label="Permalink to “15-容器监控-cAdvisor-Prometheus-Grafana”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>随着容器数量增加，单靠日志和人工巡检已经无法掌握系统健康。cAdvisor + Prometheus + Grafana 已成为容器监控的经典组合，可以让你从“感觉系统还行”变成“数据告诉我哪里不对”。</p><p>本篇文章介绍这套组合的角色分工、典型指标、实战搭建和落地建议。</p><h2 id="监控为什么是容器化环境的基础" tabindex="-1">监控为什么是容器化环境的基础 <a class="header-anchor" href="#监控为什么是容器化环境的基础" aria-label="Permalink to “监控为什么是容器化环境的基础”">​</a></h2><p>容器环境的特点是：</p><ul><li>实例数量多；</li><li>启停频繁；</li><li>资源隔离复杂；</li><li>服务间依赖紧密。</li></ul><p>这意味着你需要持续采集资源、性能与健康指标，而不是靠一次性排查。</p><h2 id="组件角色" tabindex="-1">组件角色 <a class="header-anchor" href="#组件角色" aria-label="Permalink to “组件角色”">​</a></h2><h3 id="cadvisor" tabindex="-1">cAdvisor <a class="header-anchor" href="#cadvisor" aria-label="Permalink to “cAdvisor”">​</a></h3><ul><li>负责采集容器层级的资源使用指标；</li><li>关注 CPU、内存、磁盘、网络等容器级别指标；</li><li>通常部署在每个节点上。</li></ul><h3 id="prometheus" tabindex="-1">Prometheus <a class="header-anchor" href="#prometheus" aria-label="Permalink to “Prometheus”">​</a></h3><ul><li>负责抓取指标并存储；</li><li>提供强大的查询语言 PromQL；</li><li>支持告警与数据持久化。</li></ul><h3 id="grafana" tabindex="-1">Grafana <a class="header-anchor" href="#grafana" aria-label="Permalink to “Grafana”">​</a></h3><ul><li>负责可视化展示；</li><li>将 Prometheus 指标转成仪表盘；</li><li>适合构建运营、研发、SRE 的观察面板。</li></ul><h2 id="实战搭建概览" tabindex="-1">实战搭建概览 <a class="header-anchor" href="#实战搭建概览" aria-label="Permalink to “实战搭建概览”">​</a></h2><p>典型流程为：</p><ol><li>在每个宿主机上运行 cAdvisor；</li><li>Prometheus 定期抓取 cAdvisor 指标；</li><li>Grafana 访问 Prometheus 数据源；</li><li>构建容器监控仪表盘。</li></ol><h2 id="关键指标" tabindex="-1">关键指标 <a class="header-anchor" href="#关键指标" aria-label="Permalink to “关键指标”">​</a></h2><h3 id="容器资源指标" tabindex="-1">容器资源指标 <a class="header-anchor" href="#容器资源指标" aria-label="Permalink to “容器资源指标”">​</a></h3><ul><li>CPU 使用率；</li><li>内存占用；</li><li>磁盘 I/O；</li><li>网络流量；</li><li>容器重启次数。</li></ul><h3 id="服务健康指标" tabindex="-1">服务健康指标 <a class="header-anchor" href="#服务健康指标" aria-label="Permalink to “服务健康指标”">​</a></h3><ul><li><code>up</code> 状态；</li><li>HTTP 接口响应时间；</li><li>错误率；</li><li>队列长度。</li></ul><p>这些指标能帮助你迅速定位“资源瓶颈”“异常服务”“边界故障”。</p><h2 id="常见落地实践" tabindex="-1">常见落地实践 <a class="header-anchor" href="#常见落地实践" aria-label="Permalink to “常见落地实践”">​</a></h2><h3 id="_1-先从关键服务开始" tabindex="-1">1. 先从关键服务开始 <a class="header-anchor" href="#_1-先从关键服务开始" aria-label="Permalink to “1. 先从关键服务开始”">​</a></h3><p>不必一开始把所有容器都监控起来。优先监控核心服务和关键节点，例如数据库、网关、调度服务。</p><h3 id="_2-结合告警" tabindex="-1">2. 结合告警 <a class="header-anchor" href="#_2-结合告警" aria-label="Permalink to “2. 结合告警”">​</a></h3><p>为异常指标设置告警，例如：</p><ul><li>CPU 持续高于 80%；</li><li>内存使用接近限制；</li><li>容器重启次数异常；</li><li>健康检查失败。</li></ul><h3 id="_3-设计仪表盘" tabindex="-1">3. 设计仪表盘 <a class="header-anchor" href="#_3-设计仪表盘" aria-label="Permalink to “3. 设计仪表盘”">​</a></h3><p>推荐构建三个维度仪表盘：</p><ul><li>单节点资源面板；</li><li>服务健康面板；</li><li>业务流量面板。</li></ul><h3 id="_4-观察容器生命周期" tabindex="-1">4. 观察容器生命周期 <a class="header-anchor" href="#_4-观察容器生命周期" aria-label="Permalink to “4. 观察容器生命周期”">​</a></h3><p>监控不仅看当前指标，还要关注趋势。容器启动、停止、重启的频率往往比单次峰值更重要。</p><h2 id="工程化建议" tabindex="-1">工程化建议 <a class="header-anchor" href="#工程化建议" aria-label="Permalink to “工程化建议”">​</a></h2><ul><li>将监控配置纳入版本控制；</li><li>在新容器上线前先验证监控采集是否正常；</li><li>使用服务发现自动注册 cAdvisor/Prometheus 抓取目标；</li><li>定期评估告警阈值，避免告警疲劳。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to “常见误区”">​</a></h2><ul><li>认为“日志收集就是监控”。日志是事后分析，监控是实时预警；</li><li>认为“监控太复杂，先不做”。容器化环境越大，越需要早期布局；</li><li>只看整体指标，不看容器粒度。单个容器异常往往是故障起点。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>容器监控不是“可选项”，而是现代容器平台的基础设施。cAdvisor、Prometheus 和 Grafana 的组合，能让你把容器运行状态从“感觉上正常”转成“数据可观测”。把它作为容器工程化的一部分，能显著提升系统稳定性和运维效率。</p>',41)])])}const f=a(h,[["render",n]]);export{m as __pageData,f as default};
